\label{thm:KL-applications}
Let $[x,y]$ be a lattice Bruhat interval in any Coxeter group. Let $n=\ell(x,y)$ and let $m$ be the number of coatoms in $[x,y]$. Then the following statements hold. 

\begin{enumerate}
\item The coefficients of $P_{x,y}(q)$ have no internal zeros. In other words, 
$$
[q^i]P_{x,y}(q)=0  \implies [q^{i+1}]P_{x,y}(q)=0,
$$
where $[q^i]P_{x,y}(q)$ denotes the coefficient of $q^i$ in $P_{x,y}(q)$. 
\item For every $x\leq z\leq y$,
\begin{equation*}
 P_{x,y}(q)\geq P_{x,z}(q)P_{z,y}(q)
\end{equation*}
coefficient-wise.
\item For $1\leq i\leq\lfloor(n-1)/2\rfloor$, 
\begin{equation*}
 [q^i]P_{x,y}(q)\leq\binom{m-n+i-1}{i}.
\end{equation*}
\item The equality $P_{x,y}(q)=1$ holds if and only if $[x,y]$ is Boolean.
\end{enumerate}

\label{thm:lattice-characterization}
The following are equivalent for a Bruhat interval $[x,y]$.
\begin{enumerate}
\item The Bruhat interval $[x,y]$ is a lattice.
\item The Bruhat interval $[x,y]$ is $S_3$-free.
\item The Bruhat graph $\Gamma(x,y)$ does not contain a long edge.
\item The $R$-polynomial satisfies $R_{x,y}(q)=(q-1)^{\ell(x,y)}$.
\item Every maximal chain of $[x,y]$ is a minimum-size diamond generating set.
\end{enumerate}

