\label{lem:sublevel-connectivity}
Let $[x,y]$ be a lattice Bruhat interval. For every $\varphi\in V_{x,y}$ and $t\in\mathbb{R}$, the subgraphs of $A(x,y)$ induced by
\[
\{a\in\operatorname{At}(x,y):\lambda_a(\varphi)/\lambda_a(\theta)<t\}\ \text{and}\ \{a\in\operatorname{At}(x,y):\lambda_a(\varphi)/\lambda_a(\theta)\leq t\}
\]
are connected whenever nonempty.

\label{prop:toric-Richardson}
For $x\leq y$ in a finite Weyl group, the following are equivalent:
\begin{enumerate}
\item $[x,y]$ is a lattice;
\item $R_{x,y}$ is isomorphic to an algebraic torus;
\item $\overline{R}_{x,y}$ is a toric variety.
\end{enumerate}
When these conditions hold, the torus structure on $R_{x,y}$ extends to $\overline{R}_{x,y}$, and the torus orbits in $\overline{R}_{x,y}$ are the Richardson strata $R_{a,b}$ for $x\le a\le b\le y$. Consequently, the complete face lattice of  the moment polytope $Q_{x,y}$ of $\overline{R}_{x,y}$ is given by 
\begin{equation*}
 \mathcal F(Q_{x,y})\cong\operatorname{Int}([x,y]) :=\{\varnothing\}\sqcup\{[a,b]:x\leq a\leq b\leq y\},
\end{equation*}
ordered by containment. The face indexed by $[a,b]$ has dimension $\ell(a,b)$.

\label{thm:Richardson-IH}
Let $[x,y]$ be a lattice Bruhat interval in a finite Weyl group. For $x\leq c\leq a\leq b\leq d\leq y$ and $p\in R_{a,b}$, the odd local intersection cohomology of $\overline{R}_{c,d}$ at $p$ vanishes, and
\begin{equation*}
 \sum_{i\geq0}\dim\mathrm{IH}^{2i}_p(\overline{R}_{c,d})q^i=f_{[a,b],[c,d]}(q)=P_{w_0a,w_0c}(q)P_{b,d}(q).
\end{equation*}
The odd global intersection cohomology of $\overline{R}_{x,y}$ also vanishes, and the corresponding Poincar\'e polynomial can be computed by the toric $h$-polynomial
\begin{align*}
 H_{x,y}(q)&:={\sum}_{i\geq0}\dim\mathrm{IH}^{2i}(\overline{R}_{x,y})q^i\\
 &=\sum_{x\leq a\leq b\leq y}(q-1)^{\ell(a,b)}f_{[a,b],[x,y]}(q)\\
 &=\sum_{x\leq w\leq y}q^{\ell(x,w)}P_{w_0w,w_0x}(q^{-1})P_{w,y}(q).
\end{align*}

\label{thm:rational-smoothness}
Let $[x,y]$ be a lattice Bruhat interval in a finite Weyl group, and let $n=\ell(x,y)$. The following are equivalent:
\begin{enumerate}
\item $\overline{R}_{x,y}$ is rationally smooth;
\item $Q_{x,y}$ is simple;
\item $f_{[x,x],[x,y]}(q)=1$;
\item $f_{[y,y],[x,y]}(q)=1$;
\item $P_{x,y}(q)=1$;
\item $Q_{x,y}$ is combinatorially equivalent to the $n$-cube;
\item $H_{x,y}(q)=(1+q)^n$;
\item $\Pi_{x,y}$ is a simplex;
\item $[x,y]$ is isomorphic to the Boolean lattice $B_n$.
\end{enumerate}
When these conditions hold, $H_{x,y}(q)$ also equals $\sum_i\dim H^{2i}(\overline{R}_{x,y};\mathbb Q)q^i$, and the odd ordinary cohomology vanishes.

\label{prop:kernel-coincidence}
Let $L=[x,y]$ be a lattice Bruhat interval in a Coxeter group. For every $x\leq a\leq b\leq y$, the right KLS polynomial $f_{a,b}(q)$ of $[a,b]$ associated to the Eulerian kernel equals the Kazhdan--Lusztig polynomial $P_{a,b}(q)$. If $a<b$ and $D_{a,b}$ is any polytope with complete face lattice $[a,b]$, then
\begin{equation*}
 P_{a,b}(q)=g(D_{a,b}^*;q).
\end{equation*}
Consequently, these Kazhdan--Lusztig polynomials depend only on the isomorphism types of their ranked intervals.
